import { assertEquals } from "@std/assert";
import { Lockfile } from "./lockfile.ts";

const HEADER =
  "# This file is automatically @generated by Cargo.\nversion = 4\n\n";

function block(name: string, version: string): string {
  return `[[package]]\nname = "${name}"\nversion = "${version}"\n`;
}

Deno.test("withPackagesOf: adds what isn't locked, keeps the header and what is", () => {
  const workspace = new Lockfile(`${HEADER}${block("a", "1.0.0")}`);
  const app = new Lockfile(
    `${HEADER}${block("a", "1.0.0")}\n${block("itoa", "1.0.11")}`,
  );

  assertEquals(
    workspace.withPackagesOf(app).toString(),
    `${HEADER}${block("a", "1.0.0")}\n${block("itoa", "1.0.11")}`,
  );
});

Deno.test("withPackagesOf: another version of a package is another package", () => {
  const workspace = new Lockfile(`${HEADER}${block("itoa", "1.0.18")}`);
  const app = new Lockfile(`${HEADER}${block("itoa", "1.0.11")}`);

  assertEquals(
    workspace.withPackagesOf(app).toString(),
    `${HEADER}${block("itoa", "1.0.18")}\n${block("itoa", "1.0.11")}`,
  );
});
